                ]
                input[1] = 'fastq.bz2'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }
    test("sarscov2 - nanopore_compressed_lzma") {

        when {
            process {
                """
